uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; (r/"lean/Demo/Far").mkdir(parents=True); (r/"tools").mkdir(); (r/"lean/lean-toolchain").write_text((T.ROOT/"lean/lean-toolchain").read_text()); (r/"lean/lakefile.toml").write_text("""name = "demo"\n\n[[lean_lib]]\nname = "Demo"\nglobs = ["Demo.*"]\n"""); (r/".gitignore").write_text(".lake/\n"); (r/"tools/trust-classes.json").write_text("""{"modules": {}}\n"""); T.git(r,"init","-q"); T.git(r,"add","."); T.git(r,"commit","-qm","base"); ex=T.EXAMPLES.replace("def loneFin : Fin 1 := ⟨lone 0, by decide⟩","def loneBox : {x : Nat // lone x = x} := ⟨0, by decide⟩\n\n/-- info: 0 -/\n#guard_msgs in\n#eval loneBox.val"); [(r/f"lean/Demo/{n}.lean").write_text(x) for n,x in (("Defs",T.DEFS),("Proofs",T.PROOFS),("Examples",ex),("Far/Check",T.FAR))]; T.dump(r,Path(tempfile.mkdtemp())); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:110]) for m in T.of(T.tool(r,r.parent/"run")[1],"lone")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
